/** A decoded value: an I64 arrives as a plain number, the root having
 * refused anything past 2^53 before it could get here. */
export type Decoded = boolean | number | string | BlobHandle;

function read_u32(buf: Uint8Array, at: number): number {
  return new DataView(buf.buffer, buf.byteOffset, buf.byteLength).getUint32(at, true);
}

function read_u64(buf: Uint8Array, at: number): number {
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  return view.getUint32(at, true) + view.getUint32(at + 4, true) * 4294967296;
}

/** Decode one value; returns [value, next offset]. */
export function parse_value(buf: Uint8Array, at: number): [Decoded, number] {
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const vtype = view.getUint32(at, true);
  const vlen = view.getUint32(at + 4, true);
  const end = at + 8 + ((vlen + 7) & ~7);
  if (vtype === VALUE_BOOL) return [buf[at + 8] !== 0, end];
  if (vtype === VALUE_I64) return [Number(view.getBigInt64(at + 8, true)), end];
  if (vtype === VALUE_F64) return [view.getFloat64(at + 8, true), end];
  if (vtype === VALUE_STR) return [text_decoder.decode(buf.subarray(at + 8, at + 8 + vlen)), end];
  if (vtype === VALUE_BLOB) return [new BlobHandle(read_u64(buf, at + 8)), end];
  throw new Error(`unknown value type ${vtype}`);
}

let occurrence_blob: ((handle: number) => Uint8Array) | null = null;

/** Redeem-and-release for occurrence blobs, installed by the runtime at
 * load (this module loads no library of its own). */
export function install_occurrence_blob(fn: (handle: number) => Uint8Array): void {
  occurrence_blob = fn;
}

export type ClipPayload = { clip: number; values: (Decoded | Uint8Array)[] };

/** Decode one representation: the clip kind, then its values. `clip` is a
 * SINGLE member of the clip enum and never a mask, and 0 with no values is
 * the universal empty answer. Blobs are redeemed to bytes and released here. */
export function parse_clip(buf: Uint8Array, at: number): [ClipPayload, number] {
  const clip = read_u32(buf, at);
  const count = read_u32(buf, at + 8);
  at += 16;
  const values: (Decoded | Uint8Array)[] = [];
  for (let i = 0; i < count; i++) {
    let value: Decoded | Uint8Array;
    [value, at] = parse_value(buf, at);
    if (value instanceof BlobHandle) {
      if (occurrence_blob === null) throw new Error("kaya: occurrence blob redemption is not installed");
      value = occurrence_blob(value.handle);
    }
    values.push(value);
  }
  return [{ clip, values }, at];
}

export type PickedTriple = [handle: number, name: string, local_path: string];
export type UndoPayload = {
  label: string;
  signals: [id: number, value: Decoded][];
  texts: [id: number, path: Decoded[], text: string][];
  entries: [coll: number, path: Decoded[], key: Decoded, state: [variant: number, fields: Decoded[]] | null][];
  orders: [coll: number, path: Decoded[], keys: Decoded[]][];
};

/** One decoded occurrence (header included). `id` is null for a kind this
 * vocabulary does not know; `keys` is empty when id is a widget id, else id
 * is a template node id and keys is the copy's key path. */
export type Occurrence = { kind: number; id: number | null; keys: Decoded[]; payload: unknown };

export function parse_occurrence(buf: Uint8Array): Occurrence {
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const size = view.getUint32(0, true);
  const kind = view.getUint16(4, true);
  if (![OCC_BUTTON_CLICKED, OCC_TEXT_CHANGED, OCC_TOGGLED, OCC_VALUE_CHANGED, OCC_CLOSE_REQUESTED, OCC_WINDOW_CLOSED, OCC_ALERT_RESULT, OCC_ENTRY_POPPED, OCC_BACK_REQUESTED, OCC_SECTION_SELECTED, OCC_MENU_ACTIVATED, OCC_MENU_TOGGLED, OCC_MENU_VALUE_CHANGED, OCC_FILE_DIALOG_RESULT, OCC_CLIPBOARD_RESULT, OCC_PASTED, OCC_UNDONE, OCC_REDONE, OCC_SORT_REQUESTED, OCC_DRAW_REQUESTED, OCC_TICK, OCC_DROPPED, OCC_DRAG_ENDED].includes(kind)) return { kind, id: null, keys: [], payload: null };
  if (kind === OCC_ALERT_RESULT) {
    // The alert's one answer: id + u32 choice (ALERT_CHOICE_*).
    return { kind, id: read_u64(buf, 8), keys: [], payload: read_u32(buf, 16) };
  }
  if (kind === OCC_FILE_DIALOG_RESULT) {
    const dialog = read_u64(buf, 8);
    const count = read_u32(buf, 16);
    let at = 32; // past dialog, count, pad, values count, reserved
    const files: PickedTriple[] = [];
    for (let i = 0; i < count; i++) {
      let handle: Decoded, name: Decoded, local_path: Decoded;
      [handle, at] = parse_value(buf, at);
      [name, at] = parse_value(buf, at);
      [local_path, at] = parse_value(buf, at);
      files.push([handle as number, name as string, local_path as string]);
    }
    return { kind, id: dialog, keys: [], payload: files };
  }
  if (kind === OCC_CLIPBOARD_RESULT) {
    const request = read_u64(buf, 8);
    const [clip] = parse_clip(buf, 16);
    return { kind, id: request, keys: [], payload: clip };
  }
  if ([OCC_CLOSE_REQUESTED, OCC_WINDOW_CLOSED, OCC_ENTRY_POPPED, OCC_BACK_REQUESTED].includes(kind)) {
    // Surface lifecycle records carry the surface id alone.
    return { kind, id: read_u64(buf, 8), keys: [], payload: null };
  }
  if ([OCC_SECTION_SELECTED].includes(kind)) {
    // Surface-pair records (window, section): the SECOND id keys the
    // handler; the first rides as the payload.
    return { kind, id: read_u64(buf, 16), keys: [], payload: read_u64(buf, 8) };
  }
  if ([OCC_UNDONE, OCC_REDONE].includes(kind)) {
    // One undone/redone step: the window, four run lengths, the group's
    // label, then ONE flat values tail the runs cut up — signals, texts,
    // entries, orders (docs/undo-plan.md D5; wire::undo_body).
    const window = read_u64(buf, 8);
    const n_signals = read_u32(buf, 16);
    const n_texts = read_u32(buf, 20);
    const n_entries = read_u32(buf, 24);
    const n_orders = read_u32(buf, 28);
    let at = 32;
    let label: Decoded;
    [label, at] = parse_value(buf, at);
    const count = read_u32(buf, at);
    at += 8;
    const flat: Decoded[] = [];
    for (let i = 0; i < count; i++) {
      let value: Decoded;
      [value, at] = parse_value(buf, at);
      flat.push(value);
    }
    let i = 0;
    const signals: UndoPayload["signals"] = [];
    for (let n = 0; n < n_signals; n++) {
      signals.push([flat[i] as number, flat[i + 1]!]);
      i += 2;
    }
    // Arity-first groups: `size` counts itself, so a reader takes it and
    // needs nothing else. path_len 0 means the id is a live widget id.
    const texts: UndoPayload["texts"] = [];
    for (let n = 0; n < n_texts; n++) {
      const size = flat[i] as number;
      const ident = flat[i + 1] as number;
      const path_len = flat[i + 2] as number;
      const body = flat.slice(i + 3, i + size);
      i += size;
      texts.push([ident, body.slice(0, path_len), body[path_len] as string]);
    }
    const entries: UndoPayload["entries"] = [];
    for (let n = 0; n < n_entries; n++) {
      const size = flat[i] as number;
      const coll = flat[i + 1] as number;
      const present = flat[i + 2] as number;
      const variant = flat[i + 3] as number;
      const path_len = flat[i + 4] as number;
      const body = flat.slice(i + 5, i + size);
      i += size;
      const state: [number, Decoded[]] | null = present ? [variant, body.slice(path_len + 1)] : null;
      entries.push([coll, body.slice(0, path_len), body[path_len]!, state]);
    }
    const orders: UndoPayload["orders"] = [];
    for (let n = 0; n < n_orders; n++) {
      const size = flat[i] as number;
      const coll = flat[i + 1] as number;
      const path_len = flat[i + 2] as number;
      const body = flat.slice(i + 3, i + size);
      i += size;
      orders.push([coll, body.slice(0, path_len), body.slice(path_len)]);
    }
    // A truncated or over-long body is a broken ENCODER, not bad input.
    if (i !== flat.length) throw new Error("kaya: undo delta has trailing values");
    const payload: UndoPayload = { label: label as string, signals, texts, entries, orders };
    return { kind, id: window, keys: [], payload };
  }
  const ident = read_u64(buf, 8);
  const path_len = read_u32(buf, 16);
  const keys: Decoded[] = [];
  let at = 24;
  for (let i = 0; i < path_len; i++) {
    let key: Decoded;
    [key, at] = parse_value(buf, at);
    keys.push(key);
  }
  let payload: unknown = null;
  // The u32 slot the tag family calls `reserved` is a real value on
  // these (sort_requested's column) — read before the generic tail.
  if ([OCC_SORT_REQUESTED].includes(kind)) payload = read_u32(buf, 20);
  if ([OCC_TEXT_CHANGED, OCC_TOGGLED, OCC_VALUE_CHANGED, OCC_MENU_TOGGLED, OCC_MENU_VALUE_CHANGED].includes(kind)) [payload, at] = parse_value(buf, at);
  // A paste rides a click tag VERBATIM, so the key path above is already
  // read and the clip sits after it.
  if ([OCC_PASTED].includes(kind)) [payload, at] = parse_clip(buf, at);
  if ([OCC_DRAW_REQUESTED, OCC_TICK].includes(kind)) {
    // The canvas asks carry a run of BARE values after the key path with
    // no count in front, read until the record ends (docs/canvas-plan.md §3.2.1).
    const tail: Decoded[] = [];
    while (at < size) {
      let value: Decoded;
      [value, at] = parse_value(buf, at);
      tail.push(value);
    }
    payload = tail;
  }
  return { kind, id: ident, keys, payload };
}
